export const additionalLessons=[];
function N(module,id,title,question,steps,prompt,answer,trap,quiz,code=''){
  additionalLessons.push({module,id,title,level:'P0',summary:question,points:steps.map(s=>s.split('。')[0]+'。'),tutorial:{question,steps,worked:{prompt,answer},trap},code,quiz:quiz.map((q,i)=>({id:`${id}-q${i+1}`,prompt:q[0],options:q[1],answer:q[2],explain:q[3]}))});
}
N('stm32','stm32-capture','输入捕获与频率测量','为什么捕获时间戳比在循环里数脉冲更稳？',['定时器按固定时钟计数，外部边沿到来时硬件把 CNT 锁存到 CCR，减少软件进入 ISR 延迟带来的时间戳误差。','相邻同类边沿时间差 Δcount 对应周期 Δcount/fcount，频率为 fcount/Δcount。低频还需处理溢出，高频受计数分辨率限制。','n 位计数器单次回绕可按模 2^n 计算差；若期间回绕多次，必须额外计数，否则模差失去周期数。'],'1 MHz 计数器，相邻上升沿捕获 1000 与 6000，频率？','差为 5000，周期 5000/1 MHz=5 ms，频率 200 Hz。测占空比还需要高电平宽度捕获，仅两个上升沿只能给周期。','PWM 输出与输入捕获使用同一类计数资源但数据方向不同。',[
 ['1 MHz 计数时钟，周期差 1000，频率？',['1 kHz','1 MHz','100 Hz','10 Hz'],0,'一个计数是 1 μs，1000 个是 1 ms，倒数为 1000 Hz。'],
 ['16 位计数器从 65000 到 1000、只回绕一次，差？',['1536','-64000','1000','65536'],0,'按模 65536：1000-65000+65536=1536。前提是已知最多一次回绕。'],
 ['硬件输入捕获主要锁存？',['边沿时的 CNT','任务名称','数组长度','指针类型'],0,'CCR 保存边沿时刻对应计数，ISR 可稍后读取，减少软件响应时延对测量的影响。']
]);
N('stm32','stm32-uartdma','UART DMA、IDLE 与环形接收','为什么 IDLE 不能直接当作完整帧结束？',['DMA 连续把字节写进缓冲区；IDLE 表示线路出现空闲，它反映传输间隙，不知道应用报文结构。','一条消息中途可能有间隙，多条消息也可能紧接。接收任务需要按 DMA 写入位置取出新增字节，再交给跨事件解析器。','环形缓冲绕回要分两段取数据，并处理读写赶超。中断只发布已完成范围，解析在任务执行；错误、溢出、半传输/完成事件应有策略。'],'收到半条消息触发 IDLE，随后收到剩余半条，应该丢第一半吗？','不应仅因 IDLE 丢弃。保存已收到内容与解析状态，后续字节接着处理；若超过应用超时或长度非法，再按规则重同步。','DMA 剩余计数和缓冲索引要按具体配置读取，快照与事件竞争需设计。',[
 ['IDLE 事件严格证明什么？',['线路有空闲','CRC 必然正确','恰好一整条命令','DMA 已停止'],0,'IDLE 属于 UART 线路条件，不能直接判断应用帧是否完整或有效。'],
 ['环形缓冲新增区间跨尾部时应？',['分尾部和头部两段处理','只处理头部','总把索引清零','认为收到错误'],0,'字节在物理数组分成两段，但逻辑顺序连续，应先尾部再头部。'],
 ['接收速度持续超过解析速度，最终会？',['缓冲可能被覆盖','自动无限扩容','不再需要 CRC','波特率自动下降'],0,'固定容量不能长期吸收吞吐差，应检测溢出、提高处理能力或采用流控与丢包策略。']
]);
N('protocol','p-crc','校验和与 CRC 推导','CRC 为什么比简单累加更能发现某些错误？',['简单累加忽略排列，两个字节互换可能总和不变。CRC 把位序列作为 GF(2) 多项式，用约定生成多项式做除法，异或承担无进位加减。','每输入一位，根据最高位反馈移位并可能异或多项式，最终余数成为校验字段。检错能力由多项式和消息长度等条件决定，不是随机魔法。','计算双方必须一致：宽度、多项式、初值、位反射、最终异或、覆盖范围和发送字节序，少一个条件也可能校验全错。'],'为什么同样叫 CRC-16，两个设备算出不同值？','CRC-16 只说明宽度，不能唯一确定算法。逐项核对 poly、init、refin/refout、xorout 和输入范围，再使用双方约定的测试向量。还要分清算出的数值与在线路发送的低/高字节顺序。','CRC 用于检错，不能提供加密身份认证。',[
 ['仅给“CRC-16”足以唯一实现算法吗？',['不足','足够','只要字节多就足够','只在 STM32 足够'],0,'同宽度有多种参数组合，必须提供完整参数和测试向量。'],
 ['简单累加对两个字节互换可能？',['和不变，漏检','一定检测','变成随机值','自动加密'],0,'加法交换律使 a+b 与 b+a 相同，所以位序变化可能无法体现。'],
 ['CRC 的 GF(2) 加减常对应？',['异或','普通带进位加法','浮点乘法','指针比较'],0,'系数为 0/1，模 2 下相同项抵消，异或恰好实现无进位加减。']
]);
N('protocol','p-throughput','SPI/UART 吞吐与刷新预算','为什么 SPI 时钟 20 MHz 不等于每秒 20 MB？',['时钟频率单位是每秒周期；单数据线 SPI 每周期传一位，8 位才组成一字节，所以理论字节率为 fSCK/8。','屏幕每帧像素数×每像素字节得到数据量，再除实际吞吐估算发送时间。片选间隙、命令、软件调度和绘制还会增加时间。','DMA 可以减少 CPU 搬运占用，却不增加单条线的物理比特率。双缓冲重叠绘制与发送，总周期受较慢阶段限制。'],'240×240、RGB565，每帧多少字节？20 MHz SPI 理论发送多久？','240×240×2=115200 B；20 MHz/8=2.5 MB/s，纯像素发送约 46.08 ms，理论全帧上限约 21.7 fps，实际更低。局部刷新可减少像素量。','MHz 与 MB/s、RGB565 与 RGB888 必须先统一单位。',[
 ['8 位字节、单线 8 MHz SPI 理论字节率？',['1 MB/s','8 MB/s','64 MB/s','8 B/s'],0,'一周期一位，8 周期一字节，8百万/8=1百万字节每秒。'],
 ['DMA 能否让 8 MHz 单线每周期自动发 8 位？',['不能','能','只在 STM32 能','只在低功耗能'],0,'DMA 改变数据搬运方式，不改变 SPI 线路配置下每周期的位数。'],
 ['发送 10 ms、绘制 6 ms，理想双缓冲稳定周期至少？',['约 10 ms','必为 6 ms','必为 16 ms','0 ms'],0,'两阶段可重叠，稳定吞吐受较慢 10 ms 阶段限制，仍需增加交接等开销；第一帧延迟另算。']
]);
N('rtos','r-critical','临界区、关中断与原子操作','为什么锁住任务还不能阻止 ISR 修改共享数据？',['任务 Mutex 只约束遵守同一锁的任务；ISR 不等待这个锁，因此仍可在任务临界路径中打断并修改共享对象。','端口临界区屏蔽允许范围的中断，适合短小共享状态更新，但不能在里面做阻塞等待。被保留的高紧急度 ISR 仍要有独立规则。','原子操作保护指定读写/读改写并按内存顺序发布数据，是否无锁、代价和支持情况要看工具链与平台。单核关中断也不阻止 DMA。'],'任务拿 Mutex 后读改写 count，ISR 也 count++，安全了吗？','没有，ISR 不受任务 Mutex 限制。应采用覆盖该 ISR 的合适短临界区或双方可用的原子操作，或改变设计为 ISR 发事件、单任务更新 count。','不要在关中断期间等待一个必须由中断完成的事件，这会让等待无法完成。',[
 ['任务 Mutex 是否自动禁止 ISR 访问变量？',['不会','会','只在 32 位会','只要 volatile 就会'],0,'ISR 不参与任务锁阻塞语义，必须单独处理跨上下文共享。'],
 ['临界区内适合什么？',['短共享状态更新','长时间等待 DMA 中断','网络阻塞接收','无限循环'],0,'临界区增加中断响应延迟，也可能屏蔽完成事件，必须短且不阻塞。'],
 ['CPU 关中断能停止 DMA 读写吗？',['不能','能','仅在 USART 能','只关高优先级能'],0,'DMA 是独立硬件主设备，CPU 中断屏蔽不等于暂停其传输，需要专门硬件和所有权控制。']
]);
N('rtos','r-eventloss','事件合并、计数与消息','同一个标志置位三次，为什么只看得出一次？',['布尔值只编码“有/无”。已经为真时再次写真不会保存次数；消费者清零时还可能与生产者再次置位交错丢事件。','计数信号/通知可以累计无载荷事件；位组表示不同条件；队列保存一系列独立数据。选结构前先问是否允许合并和丢弃。','处理时间与生产速度决定积压。必须定义满队列、计数溢出和超时策略，不能假定加长队列就能永久解决吞吐不足。'],'三个编码器处理事件都写 pending=true，消费者处理一次并清零，会保留三次吗？','不会，pending 不记录数量。若每次都必须处理，使用计数或数据队列；若只需读取最新状态且允许合并，布尔通知可以，但清除与再次发布仍需正确同步。','“只保留最新值”也需要区分覆盖消息和发布时的缓冲区一致性。',[
 ['要保存每次事件的不同载荷，通常选？',['消息队列','单个 bool','一个相同事件位','延时函数'],0,'队列保留独立元素与顺序，bool/同一位只表示有事件，计数只保存数量。'],
 ['刷新请求只需最终最新画面，可否允许合并？',['可以，需明确需求','永远不可以','必须重复渲染每个历史画面','只看 CPU 位数'],0,'若业务只需要最新状态，合并可减少冗余；关键是明确不要求每个历史请求独立执行。'],
 ['平均消费慢于生产，有限队列长期会？',['满，必须有策略','永不满','自动变无限','稳定保持一个'],0,'积压按两者速率差增加，容量只延后溢出，不能修复长期吞吐失衡。']
]);
N('engineering','e-fsm','状态机、超时与故障恢复','为什么状态机要把超时也当成事件？',['状态代表系统当前允许做的事，事件触发合法转换。把前置条件写在转换规则中，可以排除布尔标志乱组合。','只等待正常事件会在传感器故障或通信丢失时永远停留。每个等待状态都要定义超时事件、停止输出和恢复路径。','记录状态、事件、转换和原因，让日志能复现业务过程。重复事件处理要幂等或显式拒绝，不能重复执行危险动作。'],'WAIT_POSITION 超时还没到位，应怎样转换？','切到 FAULT 或受控停止状态，撤销电机输出并记录原因，根据需求等待人工确认或执行安全复位。不能自动继续 ACTUATE，因为缺少到位证据。','状态名不能代替执行条件；进入、退出动作及异常处理应有明确职责。',[
 ['等待状态一直收不到事件，应设计？',['超时与安全恢复','永远等待','无条件下一状态','只改变量名'],0,'外部设备可能失效，超时让系统有可控退出路径，而非永久占住资源。'],
 ['非法状态收到动作事件，应？',['按规则拒绝或记录','总立即执行','随机选择下一状态','关闭校验'],0,'事件的业务含义依赖当前状态，忽略前置条件会产生顺序错误。'],
 ['重复命令造成重复动作，可采用？',['命令号与幂等处理','只加 volatile','提高波特率','扩大栈必然解决'],0,'识别已处理命令并返回已有结果，可防止重发导致重复效果，具体记录寿命需按协议设计。']
]);
N('memory','mem-map','map 文件与内存预算','Flash 剩很多，为什么创建任务还是失败？',['Flash 固件空间与 SRAM 运行空间是不同资源。任务栈、TCB、队列和堆主要消耗可写 RAM，代码小不代表 RAM 充足。','map 文件列出段地址、符号大小、来源对象和链接布局。查看 .data/.bss、静态数组和堆栈保留，建立总预算。','运行时还要加动态峰值、分配器开销、任务栈余量和 DMA 可达区域限制。链接成功只说明静态布局满足脚本，不能证明所有动态路径安全。'],'SRAM 128 KB，静态用 90 KB、任务栈总 30 KB，还能给堆 20 KB 吗？','不能在同一 128 KB 区域无重叠容纳 90+30+20=140 KB，还没算 TCB 等开销。需要核对各区域、减少占用或重新设计；不能因为 Flash 还有空位就认为可用。','不同 SRAM 区域可能不是所有 DMA 都可访问，预算必须含地址范围。',[
 ['map 文件主要帮助查看？',['段与符号的地址和大小','实际每次运行耗时','网络丢包率','电池化学容量'],0,'它记录链接布局，可追踪某数组或模块占用，但运行时性能和动态峰值需其他测量。'],
 ['固件 Flash 只占 10%，能保证任务创建成功？',['不能','能','只要 main 小就能','优化关闭就能'],0,'任务创建消耗 RAM/堆等运行资源，与 Flash 剩余不是同一指标。'],
 ['动态内存预算应包含？',['峰值、管理开销与碎片约束','只算用户有效字节','只算 .text','只看任务个数'],0,'分配器与对齐有成本，连续块限制和同时存活对象峰值也影响能否成功。']
]);
N('c','c-pointerconst','指针声明中的 const','const 放在 * 两侧，分别限制什么？',[
  'const int *p 中 const 限定所指 int，通过 p 不能修改该 int；p 自身仍可改为指向另一个有效 int。读作“指向 const int 的指针”。',
  'int *const p 中 const 限定指针对象，初始化后不能改 p 的地址值，但若所指 int 可修改，*p 仍可写。const int *const p 同时限制两者。',
  'const 是访问约束，不能让无效地址变安全，也不表示底层对象必然从不变化。例如另一个合法非 const 别名仍可能修改本来就非 const 的对象。'
],'int a=1,b=2; const int *p=&a; p=&b; 与 *p=3 哪句合法？','p=&b 合法，因为 p 本身非 const；*p=3 违反所指对象的 const 访问约束。若改成 int *const p=&a，结论交换：*p=3 可修改 a，p=&b 不允许。','强行去掉 const 再修改本来定义为 const 的对象会有未定义行为。',[
  ['int *const p=&x; 哪个操作允许（x 为可写 int）？',['p=&y','*p=8','p++','p=NULL'],1,'const 限定的是指针 p，地址不能改变；目标 int 未被限定为 const，可通过 *p 写入 8。'],
  ['const int *p=&x; p=&y; 的结论？',['允许，改变的是指针','不允许，所有东西都 const','一定改变 x','会自动复制 y'],0,'const 约束通过 p 写目标，不约束 p 本身，因此可重新绑定有效地址。'],
  ['const int *const p 限制哪些修改？',['只限制目标','只限制地址','限制地址和通过 p 修改目标','自动保证线程安全'],2,'第一个 const 限定 int，第二个 const 限定 p，两类写入都受约束，但没有同步和原子保证。']
]);
N('c','c-doubleptr','二级指针与输出参数','要在函数里修改外部指针，为什么需要多一级？',['形参按值传递，int *p 收到调用者指针的地址值副本，给 p 赋新地址不会改外部变量。','int **pp 收到外部指针对象的地址，*pp 访问该指针对象，**pp 才访问最终 int。两次间接访问必须分别满足有效性。','输出参数要约定成功/失败时写什么、谁拥有新资源。单个二级指针不表示任意二维连续数组。'],'int *x=NULL; void set(int **pp,int *v){*pp=v;} set(&x,&a) 后？','pp 指向 x，*pp=v 写 x，使 x=&a。a 的生命周期必须覆盖 x 的使用。若直接把 x 传入，会把空值当地址，不能访问。','检查 pp 非空不意味着 *pp 也非空；两层的有效性分别判断。',[
  ['修改调用者 int *x，应传？',['x 的整数内容','&x','sizeof(x)','x++'],1,'&x 是指针变量 x 的地址，类型 int**，通过 *pp 才能改 x 的内容。'],
  ['int **pp; **pp 访问的是？',['pp 自身','最终 int 对象','数组长度','函数参数数量'],1,'第一层取得 int*，第二层沿这个地址取 int；两层都需有效。'],
  ['int m[2][3] 能直接当 int** 用吗？',['总能','不能，布局和间接访问规则不同','只要 int 为 4 字节就能','强转必然修复'],1,'二维数组行内保存整数；int** 的一次解引用期待指针对象。强转不建立不存在的指针表。']
]);
N('c','c-memcpy','memcpy、memmove 与重叠拷贝','同一数组内搬数据，为什么不能随意 memcpy？',['memcpy 要求源与目标区间不重叠，违反前提会产生未定义行为。某次实现碰巧正确不能成为保证。','重叠时正向复制可能先覆盖后面还未读取的源字节。memmove 提供如同先复制到临时区域再写回的语义，实际实现可按方向安全复制。','两者只搬字节，不处理字符串终止，不创建任意 C++ 对象的合法拷贝语义。容量和有效范围仍由调用者负责。'],'char s[6]="ABCDE"; memmove(s+1,s,4); 后前五个字符？','变为 AABCD，末尾原零仍在索引 5。目标位于源后面，安全实现可从尾部往前复制，避免 A 先覆盖 B 后影响后续读取。','strcmp 比字符串，memcmp 比字节；结构体填充字节让 memcmp 不能普遍代替字段相等比较。',[
  ['源目标重叠时，哪种字节拷贝有定义的重叠处理语义？',['memcpy','memmove','strlen','strchr'],1,'memmove 保证效果如同经临时副本，memcpy 的前提明确要求不重叠。'],
  ['memcpy 会自动在末尾追加零吗？',['会','不会','仅复制 int 时会','看操作系统位数'],1,'只复制指定 n 个字节，字符串终止需要你保证在这 n 字节里或另外写入。'],
  ['拷贝前最需要确认？',['只确认指针数值非零','可访问范围、容量与重叠前提','只确认字符编码','只确认编译通过'],1,'非空指针可能仍越界或悬空；必须验证源可读 n 字节、目标可写 n 字节，并匹配函数重叠规则。']
]);
N('c','c-ub','未定义、未指定与实现定义','笔试输出题为什么有时没有唯一正确数字？',['未定义行为意味着标准不再给该执行提出通常的结果保证，例如越界访问、有符号溢出、某些未排序重复修改。不能靠猜编译器顺序给数字。','实现定义行为由实现选择并说明，例如 C11 下负有符号数右移。未指定行为允许多个合法选择但通常不要求文档规定，例如某些表达式求值顺序。','先写清语言版本与环境，再检查表达式是否合法，最后才算值。C 与不同版本 C++ 的排序规则不完全相同。'],'按 C11，int i=1; int x=i++ + i++; 能算出固定 x 吗？','不能，两次修改同一标量在这里没有顺序关系，属于未定义行为。某次打印 3 不代表可移植规则。拆成明确顺序的语句再计算。','不要把所有不确定结果都叫未定义；正确分类能说明你理解标准边界。',[
  ['C11 有符号加法溢出属于？',['实现定义','未定义行为','总按模回绕','语法错误'],1,'标准未给有符号溢出的普通结果保证；优化可能基于不会溢出的合法程序前提。'],
  ['C11 中负有符号整数右移应怎样描述？',['普遍保证补零','实现定义，查看实现','始终编译失败','等于浮点除法'],1,'不同实现可选择规定的行为，要看实现文档，不能将常见算术右移写成普遍语言保证。'],
  ['一次运行未定义表达式输出了 3，能推出下次仍为 3？',['能','不能','关闭优化一定能','转为 64 位一定能'],1,'未定义行为没有稳定输出承诺，更换输入、编译器或优化都可能改变表现。']
]);
N('c','c-float','浮点表示与精度','0.1 为什么常不能精确表示？',['常见 IEEE 754 二进制浮点用符号、指数和有效数表示有限个二进制数。十进制 0.1 展开为无限循环二进制小数，只能取有限位近似。','算术每步可能舍入，两个不同计算路径结果可能有很小差异。判断测量值接近时用明确的绝对/相对容差，不能无条件直接比较 ==。','常见 binary32 有 24 位有效二进制精度。数量级大后相邻可表示值间距变大，加很小的数可能没有变化。浮点特征由实现和目标 FPU 决定。'],'常见 binary32 中，为什么 16777216.0f+1.0f 可能还是 16777216.0f？','在 2^24 附近，相邻可表示整数间距已达 2，+1 位于两个表示值中间。常用向最近偶数舍入时回到 16777216。不是加法没执行，而是结果表示精度有限。','容差需要贴合业务单位和范围；NaN 比较和异常值也要处理。',[
  ['0.1 在常见二进制浮点中通常是？',['精确有限二进制小数','近似值','字符串','任意精度整数'],1,'分母含 5 的因子，不能写成有限个 2 的幂分母，有限位二进制表示需要舍入。'],
  ['测量浮点值比较时通常应考虑？',['业务容差与数值范围','只比较地址','一定转 char','固定所有场景容差为 1'],0,'误差容忍取决于量纲、噪声和数值规模，可采用绝对/相对误差，不能任意指定通用阈值。'],
  ['float 和 double 的大小是否由所有 C 实现统一保证为 4/8？',['是','不是，应看实现','由字符串决定','由数组长度决定'],1,'4/8 是常见实现，语言有范围与精度要求但不能仅凭类型名字推导所有平台对象大小。']
]);
N('cpp','cpp-cast','C++ 四种类型转换','为什么 C++ 不把所有强转都写成同一个形式？',['static_cast 表达受静态类型规则约束的转换，例如某些数值或继承转换，并不自动做运行时类型安全检查。','dynamic_cast 可对多态类型进行运行时检查；指针失败返回空，引用失败抛出相应异常。const_cast 处理限定，reinterpret_cast 处理较低层的重解释，但不提供目标对象有效性保证。','转换只改变类型解释或数值，不能自动创建不存在的对象、修复对齐或延长生命周期。看到强转应先说明为什么数据本来符合目标类型的要求。'],'Base 为多态类，Base *p 实际指向另一个派生类型，dynamic_cast<Derived*>(p) 失败如何表示？','返回 nullptr，调用者先检查再用。dynamic_cast<Derived&>(*p) 失败则抛 std::bad_cast。使用运行时类型检查还需工程支持相应特性。','用 const_cast 写本来就是 const 的对象通常未定义；强转不是消除警告的通用办法。',[
  ['运行时检查多态向下转换通常用？',['dynamic_cast','const_cast','sizeof','extern'],0,'dynamic_cast 检查对象动态类型是否符合目标类型，合法前提仍包括类型和生命周期。'],
  ['失败的 dynamic_cast 指针转换返回？',['随机地址','nullptr','0xFFFFFFFF','原指针总不变'],1,'指针转换失败用空值表示，应检查再访问。引用转换则使用异常报告失败。'],
  ['reinterpret_cast 能保证非法地址变成合法对象吗？',['能','不能','只有 64 位能','仅优化后能'],1,'它不分配对象、不建立合法生命周期，也不确保对齐和可访问性。']
]);
N('cpp','cpp-slicing','对象切片与虚函数调用','为什么把 Derived 按值交给 Base 后，多态消失了？',['Base b=derived 创建的是独立 Base 对象，只复制基类部分，派生类新增状态没有进入 b；这称为对象切片。','b 的动态类型就是 Base，通过它调用虚函数也不会神奇找回原 Derived。引用或指针才能在合法生命周期内访问原派生对象。','虚函数调用依赖实际对象和调用上下文，不仅依赖是否写 virtual。构造/析构阶段按当前构造/析构中的类处理动态分派，不能调用尚未建立或已拆除的派生层。'],'void run(Base b) 与 void run(Base &b)，传 Derived 时有什么差别？','按值版本创建 Base 副本发生切片；引用版本绑定原对象，可通过虚函数分派到派生实现。引用不拥有对象，必须保证原对象活着。','常见虚表是实现方案，不能据此保证每个类都恰好多一个指针且大小固定。',[
  ['Base b=derived 常发生？',['对象切片','所有成员自动共享','动态分配','引用重绑定'],0,'按值建立 Base，仅保留基类子对象的内容，派生部分不进入新对象。'],
  ['保存多态行为通常传？',['基类引用或指针','sizeof(Base)','基类按值副本','宏名称'],0,'引用/指针访问原对象，配合虚函数动态分派；仍需生命周期与所有权约定。'],
  ['基类构造中调用虚函数，能期待调用尚未构造的派生覆盖吗？',['总能','不能如此依赖','只有成员多时能','只有析构能'],1,'构造当前基类阶段，派生部分尚未构造，虚调用按该阶段类语义处理。']
]);
N('ds','ds-lowerbound','二分边界与重复元素','如何找到第一个大于等于目标的元素？',['采用半开候选区间 [lo,hi)，初始 [0,n)。答案是分界点，左侧都小于 target，右侧都大于等于 target。','a[mid]<target 时 mid 及左边都不够大，lo=mid+1；否则 mid 可能正是第一个达标者，hi=mid，不能把 mid 排除。','lo==hi 时得到插入位置，范围是 0～n。若要确认目标存在，还要检查 lo<n 且 a[lo]==target，避免解引用尾后位置。'],'[1,2,2,2,5] 寻找第一个 >=2，用 [0,5) 怎样移动？','mid=2 值 2，hi=2；[0,2) 的 mid=1 值 2，hi=1；[0,1) 的 mid=0 值 1，lo=1；结束返回 1。每次保留可能的第一个 2。','返回 n 是合法插入位置，但不是合法元素下标。',[
  ['lower_bound 找不到足够大的元素时可返回？',['n','一定 0','随机负数','不能结束'],0,'全数组均小于目标，分界点在末尾 n，这是尾后位置，不能直接读取 a[n]。'],
  ['a[mid]>=target 时寻找首个达标位置应？',['hi=mid','lo=mid+1','直接认为唯一答案','hi=mid-1 与原半开规则混用'],0,'mid 本身可能是答案，应保留在分界候选中，hi=mid 继续缩小。'],
  ['算法要求数组满足？',['按条件单调分区','必须无重复','必须是链表','必须全部正数'],0,'核心是目标条件前假后真；升序数组符合。重复元素允许，负数也允许。']
]);
N('ds','ds-recursion','递归栈与迭代','递归为什么需要终止条件和规模缩小两件事？',['终止条件定义最小子问题的直接结果；规模缩小保证每次调用确实向这个条件靠近。仅写 if 并不保证可到达。','函数调用保存返回位置、参数与局部状态，深度决定峰值栈。时间 O(n) 的递归也可能空间 O(n)。','迭代可用显式栈表达相同待处理工作，便于限制容量；尾递归是否优化取决于实现，不能依赖 MCU 编译器一定省栈。'],'链长 n 的递归反转为什么额外空间不是 O(1)？','每个节点调用一次下层，最深有 n 层尚未返回的现场，所以 O(n) 栈。迭代用 prev/cur/next 三个指针完成，额外 O(1)，更适合严格小栈场景。','返回前的局部对象和异常路径也会影响是否能做尾调用优化。',[
  ['深度 n、每层常数空间的递归，峰值额外空间？',['O(1)','O(n)','O(n²)','O(log log n)'],1,'虽然每层只用固定空间，但 n 层可同时存在，合计随 n 增长。'],
  ['有终止判断却参数始终不变，可能？',['无限递归','自动排序','自动变迭代','栈零占用'],0,'若初值不满足终止条件且递归参数不向终止值靠近，就会持续调用直至资源耗尽。'],
  ['尾递归一定消除栈增长吗？',['一定','不保证，取决于实现和优化','仅由 CPU 位数决定','只有链表保证'],1,'语言和工具链条件可能限制优化，应查看生成代码或选择明确迭代实现。']
]);
N('ds','ds-prefix','前缀和与区间计算','多次查询区间和为什么能从 O(n) 变为 O(1)？',['定义 prefix[0]=0，prefix[i+1]=prefix[i]+a[i]，因此 prefix[k] 是前 k 个元素的总和。','半开区间 [l,r) 之和为 prefix[r]-prefix[l]，相减抵消了区间之前的共同部分。初始化 O(n)，每次查询仅一次减法。','数组改变后前缀可能失效，频繁单点更新需要其他结构；累加类型要容纳总和，不能只看单个元素不会溢出。'],'a=[2,4,1,3]，查询索引 [1,3) 的和？','前缀为 [0,2,6,7,10]，prefix[3]-prefix[1]=7-2=5，对应 4+1。半开右边界不包含索引 3。','负数不影响区间相减公式；它影响的是某些基于单调性的窗口算法。',[
  ['prefix[k] 为前 k 项和，[l,r) 和为？',['prefix[r]-prefix[l]','prefix[r]+prefix[l]','a[r]-a[l]','prefix[l]-prefix[r]'],0,'两项均包含前 l 项，相减正好留下 l 到 r-1。'],
  ['构造好前缀后单次查询复杂度？',['O(1)','O(n)','O(n²)','O(2^n)'],0,'固定访问两个位置并相减，不随区间长度增长。预处理仍需 O(n)。'],
  ['改变 a[0] 后原前缀是否还可直接使用？',['总可','不可以，相关前缀需更新','只改变量名即可','只影响最后查询'],1,'a[0] 参与所有非零长度前缀，旧值已不再对应当前数组。']
]);
